const i = $input.first();
const j = i.json;
const p = j.payload || j;
const mode = p.mode || j.transcription_mode || 'production';
const provider = p.provider || j.transcription_provider || null;
const model = p.model || j.transcription_model || null;
const allowed = new Set(['openai:gpt-transcribe', 'gemini:gemini-3.5-transcribe']);

if (mode === 'production' && (!provider || !model)) {
  throw new Error('TRANSCRIPTION_PRIMARY_NOT_SELECTED: run approved benchmark before production routing (AI-DEC-007)');
}

if (!provider || !model || !allowed.has(`${provider}:${model}`)) {
  throw new Error('TRANSCRIPTION_PROVIDER_MODEL_NOT_APPROVED: provider and model must match approved registry');
}

return [{
  json: {
    ...j,
    transcription_mode: mode,
    transcription_provider: provider,
    transcription_model: model
  },
  binary: i.binary
}];

const item = $input.first();
const j = item.json;
const p = j.payload || j;
const bin = item.binary?.data;

if (!bin) {
  throw new Error('AUDIO_BINARY_REQUIRED: missing binary.data for Gemini transcription');
}

let buffer = null;
if (this.helpers && typeof this.helpers.getBinaryDataBuffer === 'function') {
  buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
} else if (bin.data) {
  buffer = Buffer.isBuffer(bin.data) ? bin.data : Buffer.from(bin.data, 'base64');
}

if (!buffer || buffer.length === 0) {
  throw new Error('AUDIO_BINARY_LENGTH_REQUIRED: binary audio buffer is empty or missing');
}

const exactByteLength = buffer.length;
if (!Number.isSafeInteger(exactByteLength) || exactByteLength <= 0) {
  throw new Error('AUDIO_BINARY_LENGTH_REQUIRED: exact numeric byte length is invalid');
}

if (p.file_size !== undefined && p.file_size !== null) {
  if (typeof p.file_size !== 'number' || !Number.isSafeInteger(p.file_size) || p.file_size <= 0) {
    throw new Error('AUDIO_BINARY_LENGTH_REQUIRED: payload file_size must be a positive integer');
  }
  if (p.file_size !== exactByteLength) {
    throw new Error('AUDIO_BINARY_LENGTH_MISMATCH: payload file_size (' + p.file_size + ') does not match binary buffer length (' + exactByteLength + ')');
  }
}

const rawMime = (bin.mimeType || p.mime_type || '').trim().toLowerCase();
if (!rawMime) {
  throw new Error('AUDIO_MIME_TYPE_REQUIRED: audio MIME type is missing');
}

if (p.mime_type && bin.mimeType && p.mime_type.trim().toLowerCase() !== bin.mimeType.trim().toLowerCase()) {
  throw new Error('AUDIO_MIME_TYPE_MISMATCH: payload mime_type (' + p.mime_type + ') does not match binary mimeType (' + bin.mimeType + ')');
}

const allowedMimes = new Set([
  'audio/wav', 'audio/mp3', 'audio/aiff', 'audio/aac', 'audio/ogg', 'audio/flac',
  'audio/mpeg', 'audio/m4a', 'audio/l16', 'audio/opus', 'audio/alaw', 'audio/mulaw', 'audio/webm'
]);

if (!allowedMimes.has(rawMime)) {
  throw new Error('GEMINI_UNSUPPORTED_AUDIO_MIME: MIME type ' + rawMime + ' is not supported by Gemini API');
}

return [{
  json: {
    ...j,
    exact_byte_length: exactByteLength,
    mime_type: rawMime
  },
  binary: item.binary
}];

const item = $input.first();
const j = item.json;
const headers = j.headers || {};
const uploadUrl = headers['x-goog-upload-url'] || headers['X-Goog-Upload-URL'] || j['x-goog-upload-url'] || null;
if (!uploadUrl) {
  throw new Error('GEMINI_FILES_API_START_FAILED: x-goog-upload-url header not returned by Files API');
}
const prev = $('Validate Gemini Binary Metadata').first().json;
const originalBinary = $('Validate Gemini Binary Metadata').first().binary;
if (!originalBinary || !originalBinary.data) {
  throw new Error('GEMINI_AUDIO_BINARY_MISSING: binary audio data not preserved for finalize');
}
return [{
  json: {
    ...prev,
    upload_session_url: uploadUrl
  },
  binary: originalBinary
}];

const j = $input.first().json;
const ctx = $('Validate Transcription Contract').first().json;

if (j.file && j.file.state && j.file.state === 'FAILED') {
  throw new Error('GEMINI_FILE_STATE_FAILED: Uploaded file state is FAILED');
}

const text = j.text || j.transcript || j.output?.[0]?.text || j.output?.text || j.candidates?.[0]?.content?.parts?.[0]?.text || j.output_text || null;
if (!text || !String(text).trim()) {
  throw new Error('EMPTY_TRANSCRIPTION: provider returned empty transcript');
}

const inputTokens = j.usage?.prompt_tokens ?? j.usageMetadata?.promptTokenCount ?? null;
const outputTokens = j.usage?.completion_tokens ?? j.usageMetadata?.candidatesTokenCount ?? null;
const reqId = j.id || j.responseId || j.interaction_id || null;
const durationMs = ctx.payload?.duration_ms || ctx.duration_ms || null;
const audioSec = durationMs ? Number((durationMs / 1000).toFixed(2)) : (j.duration ? Number(j.duration) : null);
const lang = j.language || (Array.isArray(j.language_codes) && j.language_codes.length > 0 ? j.language_codes[0] : (typeof j.language_code === 'string' ? j.language_code : null));

return [{
  json: {
    ...ctx,
    transcript_text: String(text).trim(),
    transcript_language: lang,
    provider_request_id: reqId,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    audio_seconds: audioSec,
    estimated_cost_usd: null,
    pricing_version: null,
    raw_provider_metadata: {
      has_segments: Array.isArray(j.segments),
      has_words: Array.isArray(j.words)
    }
  }
}];

const norm = $('Normalize Transcription Output').first().json;
const sourceRes = $('Persist Literal Transcription').first().json.res;
const stId = sourceRes.source_text_id || (typeof sourceRes === 'string' ? JSON.parse(sourceRes).source_text_id : null);
const usageId = $('Record Transcription AI Usage').first().json.id;

return [{
  json: {
    ok: true,
    status: 'completed',
    ingestion_id: norm.ingestion_id,
    asset_id: norm.asset_id,
    source_text_id: stId,
    transcript_text: norm.transcript_text,
    provider: norm.transcription_provider,
    model: norm.transcription_model,
    usage_id: usageId
  }
}];
